using Microsoft.Extensions.AI;
using System.ComponentModel;
using System.Text.Json;

Console.WriteLine("Research Agent Starting...");

// Configure the chat client (uses OpenAI-compatible endpoint)
var endpoint = Environment.GetEnvironmentVariable("AI_ENDPOINT") ?? "https://api.openai.com/v1";
var model = Environment.GetEnvironmentVariable("AI_MODEL") ?? "gpt-4o";
var apiKey = Environment.GetEnvironmentVariable("AI_API_KEY")
    ?? throw new InvalidOperationException("Set the AI_API_KEY environment variable.");

var openAiClient = new OpenAI.OpenAIClient(apiKey);
IChatClient chatClient = new ChatClientBuilder(
        openAiClient.GetChatClient(model).AsIChatClient())
    .UseFunctionInvocation()
    .Build();

// Instantiate the tools
var researchTools = new ResearchTools();

var chatOptions = new ChatOptions
{
    Tools = [
        AIFunctionFactory.Create(researchTools.SearchWeb),
        AIFunctionFactory.Create(researchTools.TakeNote),
        AIFunctionFactory.Create(researchTools.GetNotes),
    ]
};

// Determine the research topic
var topic = args.Length > 0
    ? string.Join(' ', args)
    : "the latest advances in quantum computing in 2026";

Console.WriteLine($"\nResearching: {topic}\n");

List<ChatMessage> messages =
[
    new(ChatRole.System, """
        You are a research agent. Your goal is to research a topic thoroughly by:
        1. Searching the web for relevant information (make multiple searches with different queries)
        2. Taking notes on key findings as you go
        3. After gathering enough information, reviewing your notes and providing a final summary

        Always take notes on important findings before moving to the next search.
        When you have enough information, retrieve all your notes and write a comprehensive summary.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
];

// Run the agent loop
var response = await chatClient.GetResponseAsync(messages, chatOptions);

Console.WriteLine("\n=== Research Summary ===\n");
Console.WriteLine(response.Text);

if (researchTools.NoteCount > 0)
{
    Console.WriteLine($"\n[Agent took {researchTools.NoteCount} notes during research]");
}

/// <summary>
/// Tools available to the research agent.
/// </summary>
sealed class ResearchTools
{
    private readonly List<string> _notes = [];
    private readonly HttpClient _http = new();

    public int NoteCount => _notes.Count;

    [Description("Search the web for information on a query. Returns a list of search result snippets.")]
    public async Task<string> SearchWeb([Description("The search query")] string query)
    {
        Console.WriteLine($"  [Searching: \"{query}\"]");

        try
        {
            // Use a public search API (DuckDuckGo instant answer API)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var json = await _http.GetStringAsync(url);
            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            var results = new List<string>();

            // Abstract/summary
            var abstractText = root.GetProperty("Abstract").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
                results.Add($"Summary: {abstractText}");

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var item in topics.EnumerateArray().Take(5))
                {
                    var text = item.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    if (!string.IsNullOrWhiteSpace(text))
                        results.Add(text);
                }
            }

            if (results.Count == 0)
                return $"No detailed results found for '{query}'. Try a different search query.";

            return string.Join("\n\n", results);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Take a note to remember an important finding during research.")]
    public string TakeNote(
        [Description("A concise title for the note")] string title,
        [Description("The content of the note")] string content)
    {
        _notes.Add($"## {title}\n{content}");
        Console.WriteLine($"  [Note taken: \"{title}\"]");
        return $"Note saved: {title}";
    }

    [Description("Retrieve all notes taken during research so far.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes have been taken yet.";

        Console.WriteLine($"  [Reviewing {_notes.Count} notes]");
        return string.Join("\n\n---\n\n", _notes);
    }
}

